def transform(g):
 h,w=len(g),len(g[0])
 # horizontal full-color seed rows
 rows=[]
 for i,row in enumerate(g):
  if row[0]!=0 and all(v==row[0] for v in row): rows.append((i,row[0]))
 if rows:
  k=len(rows); mp={i%k:c for i,c in rows}
  if len(mp)==k: return [[mp[r%k] for _ in range(w)] for r in range(h)]
 # diagonal stripe seed lines, d=c-r
 ds={}
 for r in range(h):
  for c in range(w):
   if g[r][c]:
    d=c-r
    if d in ds and ds[d]!=g[r][c]: return None
    ds[d]=g[r][c]
 k=len(ds); mp={d%k:c for d,c in ds.items()}
 if len(mp)<k:return None
 return [[mp[(c-r)%k] for c in range(w)] for r in range(h)]
